/* hover-line-sweep: the resting underline (::after) shrinks to the right, then a new one
   (::before) grows in from the left. */
.impulsespace-sweep-link::before,
.impulsespace-sweep-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 1px;
  background: currentColor;
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.impulsespace-sweep-link::before {
  transform: scaleX(0);
  transform-origin: left;
}
.impulsespace-sweep-link::after {
  transform: scaleX(1);
  transform-origin: right;
  transition-delay: 0s;
}
.impulsespace-sweep-link:hover::before,
.impulsespace-sweep-link:focus-visible::before {
  transform: scaleX(1);
  transition-delay: 0.2s;
}
.impulsespace-sweep-link:hover::after,
.impulsespace-sweep-link:focus-visible::after {
  transform: scaleX(0);
}

@media (prefers-reduced-motion: reduce) {
  .impulsespace-sweep-link::before {
    display: none;
  }
  .impulsespace-sweep-link::after,
  .impulsespace-sweep-link:hover::after {
    transform: none;
    transition: none;
  }
}

import type { ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./impulsespace-sweep-link.css";

export interface ImpulsespaceSweepLinkProps {
  /** the label (set in uppercase mono) */
  children: ReactNode;
  /** where it goes */
  href: string;
  className?: string;
}

/** Uppercase mono link at 50% ink whose underline sweeps out and back in on hover. */
export function ImpulsespaceSweepLink({ children, href, className }: ImpulsespaceSweepLinkProps) {
  return (
    <a
      href={href}
      className={cn(
        "impulsespace-sweep-link relative inline-block font-mono text-sm leading-[1.5] tracking-[0.08em] text-foreground/50 uppercase",
        "transition-colors duration-150 ease-[cubic-bezier(0.4,0,0.2,1)] hover:text-foreground/70 motion-reduce:transition-none",
        className,
      )}
    >
      {children}
    </a>
  );
}
